	},
	sections = {
		{
			title = "Summary",
			text = [=[Harpies are winged creatures of {link:kalimdor}Kalimdor{/link}, with the bodies of women and the wings and talons of birds. They are cruel, cunning and vicious, and they prey on travellers from their nests in the high places.]=],
		},
		{
			title = "Origins",
			text = [=[The origins of the harpies are not recorded in any chronicle known to this record.]=],
		},
		{
			title = "Nature and Customs",
			text = [=[Harpies live in flocks ruled by matriarchs. They nest on cliffs and ridges and swoop down on anything weaker than themselves. They are fond of stolen shiny things and of the flesh of those they catch. Their witches command dark magic.]=],
		},
		{
			title = "In the Present Day",
			text = [=[The {link:windfury-harpies}Windfury harpies{/link} nest on the ridges of {link:mulgore}Mulgore{/link}, to the great annoyance of the {link:tauren}tauren{/link}. The Witchwing roost in {link:the-barrens}The Barrens{/link}, the Bloodfury in the {link:stonetalon-mountains}Stonetalon Mountains{/link}, and the Northspring in {link:feralas}Feralas{/link}. The roads of {link:kalimdor}Kalimdor{/link} are not safe beneath their nests.]=],
		},
	},
})

Add({
	kind = "topic",
	id = "troggs",
	title = "Troggs",
	aliases = { "trogg" },
	category = "people",
	unlock = {
		{ type = "read" },
	},
	sections = {
		{
			title = "Summary",
			text = [=[Troggs are brutish, stone-skinned creatures who live deep beneath the earth. They are strong, stupid and endlessly aggressive. For ages they were hidden in the depths. Now they have come to the surface, and they have brought ruin with them.]=],
		},
		{
			title = "Origins",
			text = [=[The records of {link:uldaman}Uldaman{/link} tell that the troggs were made by the titans, like the earthen. They were a flawed creation, and the titans sealed them away in the deep vaults of the world. The {link:explorers-league}Explorers' League{/link} believes that the dwarves disturbed those vaults while digging in Uldaman, and that the troggs have been spreading ever since.]=],
		},
		{
			title = "Nature and Customs",
			text = [=[Troggs live in tribes led by the strongest among them. Their shamans wield a crude earth magic. They care little for anything but fighting and eating.]=],
		},
		{
			title = "In the Present Day",
			text = [=[The troggs rose beneath {link:gnomeregan}Gnomeregan{/link} and drove the gnomes from their city. They fight the dwarves in {link:dun-morogh}Dun Morogh{/link} and {link:loch-modan}Loch Modan{/link}, and they swarm through {link:uldaman}Uldaman{/link} and the {link:badlands}Badlands{/link}. Wherever the dwarves dig deep, they fear to find more.]=],
		},
	},
})

Add({
	kind = "topic",
	id = "ogres",
	title = "Ogres",
	aliases = { "ogre" },
	category = "people",
	unlock = {
		{ type = "read" },
	},
	sections = {
		{
			title = "Summary",
			text = [=[Ogres are huge, dull-witted brutes of great strength. Some have two heads, and a few of them are cunning sorcerers. Most of them came to {link:azeroth}Azeroth{/link} with the orcs from Draenor, and many clans now dwell in the wild places of both continents.]=],
		},
		{
			title = "Origins",
			text = [=[The ogres served the orcish {link:horde}Horde{/link} in the {link:second-war}Second War{/link}. The warlock {link:gul-dan}Gul'dan{/link} gave some of them the gift of spellcraft, and these ogre magi became feared across the {link:eastern-kingdoms}Eastern Kingdoms{/link}. The greatest of them, Cho'gall, led the {link:twilight-s-hammer}Twilight's Hammer{/link} clan. After the Horde's defeat, the ogre clans scattered into the hills and mountains.]=],
		},
		{
			title = "Nature and Customs",
			text = [=[Ogres are warlike and greedy. They respect only strength and fight among themselves for leadership. Their chieftains rule by the club, and their magi by fear.]=],
		},
		{
			title = "In the Present Day",
			text = [=[Ogre clans hold the hills of {link:redridge-mountains}Redridge{/link}, {link:stranglethorn-vale}Stranglethorn Vale{/link}, {link:alterac-mountains}Alterac{/link} and the {link:arathi-highlands}Arathi Highlands{/link}. In {link:kalimdor}Kalimdor{/link}, the Gordunni haunt {link:feralas}Feralas{/link}, and the Gordok rule the ruins of {red:dire-maul}Dire Maul{/red}. In {link:dustwallow-marsh}Dustwallow Marsh{/link}, the Stonemaul clan has fallen from its old strength, and some of its ogres now live alongside the orcs.]=],
		},
	},
})

Add({
	kind = "topic",
	id = "naga",
	title = "Naga",
	aliases = { "naga" },
	category = "people",
	unlock = {
		{ type = "read" },
	},
	sections = {
		{
			title = "Summary",
			text = [=[The naga are serpentine creatures of the deep seas. They were once night elves of the Highborne caste. Now they have scaled tails and cruel faces, and they have returned from the depths to trouble the shores of the world.]=],
		},
		{
			title = "Origins",
			text = [=[When the {link:well-of-eternity}Well of Eternity{/link} was destroyed in the {link:great-sundering}Great Sundering{/link}, the palace of {link:queen-azshara}Queen Azshara{/link} was swallowed by the sea with all her court. Something in the depths saved them, and changed them. The drowned Highborne became the naga. For ten thousand years they dwelt hidden beneath the waves. In the time of the {link:third-war}Third War{/link} they rose again, and they served {link:illidan-stormrage}Illidan Stormrage{/link} for a time.]=],
		},
		{
			title = "Nature and Customs",
			text = [=[The naga are proud, bitter and ambitious. Their sirens are powerful sorceresses who command the waters and the storms. Their myrmidons are fearsome warriors. It is said that they still honor {link:azshara}Azshara{/link} in the deeps.]=],
		},
		{
			title = "In the Present Day",
			text = [=[The naga have claimed stretches of coast in {link:azshara}Azshara{/link}, {link:darkshore}Darkshore{/link}, {link:ashenvale}Ashenvale{/link} and {link:desolace}Desolace{/link}. They haunt the flooded temple of {link:blackfathom-deeps}Blackfathom Deeps{/link}. What they seek on the shores of {link:kalimdor}Kalimdor{/link}, the night elves do not know.]=],
		},
	},
})

